  fs.writeFileSync(path.join(worktreeRoot, fileName), 'change\n');
  execFileSync('git', ['add', fileName], { cwd: worktreeRoot });
  execFileSync('git', ['commit', '-q', '-m', 'change'], { cwd: worktreeRoot });
}

