    const next = preflightUnitWorktree({ ...gitArgs, scope: ['**'] });
    assert.equal(commitUnitWork({ ...gitArgs, baseline: next.baseline, unitId: 'u1', summary: 'again', scope: ['**'] }).status, 'no-changes');
  } finally {
    custody?.release();
    fs.rmSync(base, { recursive: true, force: true });
  }
