      s1: {
        units: {
          u1: {
            results: [
              { seat: 'member-1', role: 'producer', round: 1, outcome: 'pass', binding: { executor: 'claude-herdr', invocation: 'i1', model: 'sonnet', persona: 'p' }, runResult: { policy: { providerModel: 'claude' } } },
